-- DBWarp Blueprint 1.6 Oracle Basic preview - DBA capture
-- Server family: oracle-21c
-- Run through capture.sh or capture.ps1 as the dedicated collector account.
-- Do not run as SYS, SYSTEM, or a broadly privileged DBA account.
-- The protected raw spool is sanitized locally into the transferable spool.
-- Both contain real catalogue names and must stay inside your organisation.
-- Generated from DBWarp Blueprint's Oracle Basic catalogue queries. Do not edit.
-- POSIX cksum: 0223434411
SET ECHO OFF
SET VERIFY OFF
SET FEEDBACK OFF
SET HEADING OFF
SET PAGESIZE 0
SET LINESIZE 32767
SET LONG 32767
SET LONGCHUNKSIZE 32767
SET WRAP OFF
SET TRIMOUT ON
SET TRIMSPOOL ON
SET TERMOUT OFF
SET TIMING OFF
SET AUTOPRINT OFF
SET AUTOTRACE OFF
SET PAUSE OFF
SET SQLCASE MIXED
SET ROWLIMIT OFF
SET CMDSEP OFF
SET SQLTERMINATOR ";"
SET MARKUP HTML OFF
SET MARKUP CSV OFF
SET DEFINE OFF
WHENEVER OSERROR EXIT FAILURE
WHENEVER SQLERROR EXIT SQL.SQLCODE
ALTER SESSION SET NLS_NUMERIC_CHARACTERS = '.,';
ALTER SESSION SET NLS_CALENDAR = 'GREGORIAN';
ALTER SESSION SET NLS_DATE_FORMAT = 'YYYY-MM-DD"T"HH24:MI:SS';
ALTER SESSION SET NLS_TIMESTAMP_FORMAT = 'YYYY-MM-DD"T"HH24:MI:SS.FF9';
ALTER SESSION SET NLS_COMP = 'BINARY';
ALTER SESSION SET NLS_SORT = 'BINARY';
DECLARE
C_EXPECTED_MAJOR CONSTANT PLS_INTEGER := 21;
C_EXPECTED_MINOR CONSTANT PLS_INTEGER := -1;
C_HEX_DIGITS CONSTANT VARCHAR2(16) := '0123456789ABCDEF';
V_INPUT CLOB := :DBWARP_BP_OWNER_HEX_LIST;
V_START PLS_INTEGER := 1;
V_STOP PLS_INTEGER;
V_HEX VARCHAR2(256);
V_PREVIOUS_HEX VARCHAR2(256);
V_OWNER VARCHAR2(128);
V_OWNER_COUNT PLS_INTEGER := 0;
V_OWNER_PRESENT PLS_INTEGER;
V_SERVER_VERSION VARCHAR2(64);
FUNCTION HEX_COMPARE(P_LEFT VARCHAR2, P_RIGHT VARCHAR2) RETURN PLS_INTEGER IS
V_LIMIT PLS_INTEGER := LEAST(LENGTH(P_LEFT), LENGTH(P_RIGHT));
V_LEFT PLS_INTEGER;
V_RIGHT PLS_INTEGER;
BEGIN
FOR I IN 1 .. V_LIMIT LOOP
V_LEFT := INSTR(C_HEX_DIGITS, SUBSTR(P_LEFT, I, 1));
V_RIGHT := INSTR(C_HEX_DIGITS, SUBSTR(P_RIGHT, I, 1));
IF V_LEFT < V_RIGHT THEN RETURN -1; END IF;
IF V_LEFT > V_RIGHT THEN RETURN 1; END IF;
END LOOP;
IF LENGTH(P_LEFT) < LENGTH(P_RIGHT) THEN RETURN -1; END IF;
IF LENGTH(P_LEFT) > LENGTH(P_RIGHT) THEN RETURN 1; END IF;
RETURN 0;
END;
BEGIN
IF SYS_CONTEXT('USERENV', 'CON_NAME') = 'CDB$ROOT' THEN
RAISE_APPLICATION_ERROR(-20005, 'connect-to-pdb');
END IF;
SELECT VERSION INTO V_SERVER_VERSION FROM SYS.V_$INSTANCE;
IF TO_NUMBER(REGEXP_SUBSTR(V_SERVER_VERSION, '^[0-9]+')) <> C_EXPECTED_MAJOR OR
(C_EXPECTED_MINOR >= 0 AND
TO_NUMBER(REGEXP_SUBSTR(V_SERVER_VERSION, '[0-9]+', 1, 2)) <> C_EXPECTED_MINOR) THEN
RAISE_APPLICATION_ERROR(-20004, 'wrong-script-family');
END IF;
IF V_INPUT IS NULL OR NOT REGEXP_LIKE(V_INPUT, '^[0-9A-F]+(,[0-9A-F]+)*$') THEN
RAISE_APPLICATION_ERROR(-20001, 'owner-input');
END IF;
LOOP
V_STOP := INSTR(V_INPUT, ',', V_START);
IF V_STOP = 0 THEN V_STOP := LENGTH(V_INPUT) + 1; END IF;
V_HEX := SUBSTR(V_INPUT, V_START, V_STOP - V_START);
IF MOD(LENGTH(V_HEX), 2) <> 0 OR LENGTH(V_HEX) > 256 OR
(V_PREVIOUS_HEX IS NOT NULL AND HEX_COMPARE(V_PREVIOUS_HEX, V_HEX) >= 0) THEN
RAISE_APPLICATION_ERROR(-20001, 'owner-input');
END IF;
V_OWNER := UTL_I18N.RAW_TO_CHAR(HEXTORAW(V_HEX), 'AL32UTF8');
IF V_OWNER IS NULL OR LENGTHB(V_OWNER) > 128 OR REGEXP_LIKE(V_OWNER, '[[:cntrl:]]') THEN
RAISE_APPLICATION_ERROR(-20001, 'owner-input');
END IF;
V_OWNER_COUNT := V_OWNER_COUNT + 1;
IF V_OWNER_COUNT > 16384 THEN
RAISE_APPLICATION_ERROR(-20001, 'owner-input');
END IF;
V_PREVIOUS_HEX := V_HEX;
EXIT WHEN V_STOP > LENGTH(V_INPUT);
V_START := V_STOP + 1;
END LOOP;
BEGIN
EXECUTE IMMEDIATE
'SELECT COUNT(*) FROM SYS.ALL_USERS '
|| 'WHERE RAWTOHEX(UTL_I18N.STRING_TO_RAW(USERNAME, ''AL32UTF8'')) IN ('
|| 'SELECT CAST(REGEXP_SUBSTR(:OWNER_LIST, ''[^,]+'', 1, LEVEL) '
|| 'AS VARCHAR2(256)) FROM DUAL CONNECT BY LEVEL <= '
|| 'REGEXP_COUNT(:OWNER_LIST, '','') + 1)'
INTO V_OWNER_PRESENT USING V_INPUT, V_INPUT;
IF V_OWNER_PRESENT <> V_OWNER_COUNT THEN
RAISE_APPLICATION_ERROR(-20006, 'owner-not-found');
END IF;
EXCEPTION
WHEN OTHERS THEN
-- ALL_USERS is normally public but may be revoked
-- on hardened estates. In that case the converter proves each
-- owner from the granted floor catalogues instead.
IF SQLCODE NOT IN (-942, -1031) THEN RAISE; END IF;
END;
END;
/
WHENEVER SQLERROR CONTINUE NONE
SPOOL dbwarp-blueprint-oracle-basic.raw
