TO_CHAR(SYS_EXTRACT_UTC(SYSTIMESTAMP), 'YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"'),
'AL32UTF8')) FROM DUAL;
SELECT 'DBWARP_BP_RAW|M|PRINCIPAL|T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(
SYS_CONTEXT('USERENV', 'SESSION_USER'), 'AL32UTF8')) FROM DUAL;
SELECT 'DBWARP_BP_RAW|M|DATABASE|T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(
SYS_CONTEXT('USERENV', 'DB_NAME') || '/' || SYS_CONTEXT('USERENV', 'CON_NAME'),
'AL32UTF8')) FROM DUAL;
SELECT 'DBWARP_BP_RAW|M|SERVER_VERSION|T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(
VERSION, 'AL32UTF8')) FROM SYS.V_$INSTANCE;
SELECT 'DBWARP_BP_RAW|M|CLIENT_RELEASE|T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(
:DBWARP_BP_CLIENT_RELEASE, 'AL32UTF8')) FROM DUAL;
SELECT 'DBWARP_BP_RAW|O|' || TO_CHAR(LEVEL, 'FM99999999999999999990') || '|T' ||
CAST(REGEXP_SUBSTR(:DBWARP_BP_OWNER_HEX_LIST, '[^,]+', 1, LEVEL)
AS VARCHAR2(256))
FROM DUAL
CONNECT BY LEVEL <= REGEXP_COUNT(:DBWARP_BP_OWNER_HEX_LIST, ',') + 1;
