CASE WHEN q.username IS NULL THEN 'N' WHEN UTL_RAW.LENGTH(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.username), 'AL32UTF8')) > 1000 THEN 'L' ELSE 'T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.username), 'AL32UTF8')) END || '|' ||
CASE WHEN q.oracle_maintained IS NULL THEN 'N' WHEN UTL_RAW.LENGTH(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.oracle_maintained), 'AL32UTF8')) > 1000 THEN 'L' ELSE 'T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.oracle_maintained), 'AL32UTF8')) END || '|Z' AS DBWARP_BP_FULL_FRAME
