FROM (SELECT product, version, version_full FROM SYS.PRODUCT_COMPONENT_VERSION) q) DBWARP_BP_BOUNDED_ROWS;
PROMPT DBWARP_BP_RAW|Q|25|E
PROMPT DBWARP_BP_RAW|Q|26|oracle-database|V_$DATABASE|4|B
SELECT CASE
WHEN LENGTH(DBWARP_BP_FULL_FRAME) > 32000 THEN
TO_CLOB('DBWARP_BP_RAW|R|26|') ||
TO_CHAR(DBWARP_BP_ROW_NUMBER, 'FM99999999999999999990') ||
'|L|N|N|N|Z'
ELSE DBWARP_BP_FULL_FRAME
END AS DBWARP_BP_FRAME
FROM (SELECT ROWNUM AS DBWARP_BP_ROW_NUMBER,
TO_CLOB('DBWARP_BP_RAW|R|26|') ||
TO_CHAR(ROWNUM, 'FM99999999999999999990') || '|' ||
CASE WHEN q.platform_name IS NULL THEN 'N' WHEN UTL_RAW.LENGTH(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.platform_name), 'AL32UTF8')) > 1000 THEN 'L' ELSE 'T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.platform_name), 'AL32UTF8')) END || '|' ||
CASE WHEN q.database_role IS NULL THEN 'N' WHEN UTL_RAW.LENGTH(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.database_role), 'AL32UTF8')) > 1000 THEN 'L' ELSE 'T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.database_role), 'AL32UTF8')) END || '|' ||
CASE WHEN q.open_mode IS NULL THEN 'N' WHEN UTL_RAW.LENGTH(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.open_mode), 'AL32UTF8')) > 1000 THEN 'L' ELSE 'T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.open_mode), 'AL32UTF8')) END || '|' ||
CASE WHEN q.cdb IS NULL THEN 'N' WHEN UTL_RAW.LENGTH(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.cdb), 'AL32UTF8')) > 1000 THEN 'L' ELSE 'T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.cdb), 'AL32UTF8')) END || '|Z' AS DBWARP_BP_FULL_FRAME
FROM (SELECT platform_name, database_role, open_mode, cdb FROM SYS.V_$DATABASE) q) DBWARP_BP_BOUNDED_ROWS;
PROMPT DBWARP_BP_RAW|Q|26|E
PROMPT DBWARP_BP_RAW|Q|27|oracle-instance|V_$INSTANCE|3|B
SELECT CASE
WHEN LENGTH(DBWARP_BP_FULL_FRAME) > 32000 THEN
TO_CLOB('DBWARP_BP_RAW|R|27|') ||
TO_CHAR(DBWARP_BP_ROW_NUMBER, 'FM99999999999999999990') ||
'|L|N|N|Z'
ELSE DBWARP_BP_FULL_FRAME
END AS DBWARP_BP_FRAME
FROM (SELECT ROWNUM AS DBWARP_BP_ROW_NUMBER,
TO_CLOB('DBWARP_BP_RAW|R|27|') ||
TO_CHAR(ROWNUM, 'FM99999999999999999990') || '|' ||
CASE WHEN q.version IS NULL THEN 'N' WHEN UTL_RAW.LENGTH(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.version), 'AL32UTF8')) > 1000 THEN 'L' ELSE 'T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.version), 'AL32UTF8')) END || '|' ||
CASE WHEN q.status IS NULL THEN 'N' WHEN UTL_RAW.LENGTH(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.status), 'AL32UTF8')) > 1000 THEN 'L' ELSE 'T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.status), 'AL32UTF8')) END || '|' ||
CASE WHEN q.parallel IS NULL THEN 'N' WHEN UTL_RAW.LENGTH(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.parallel), 'AL32UTF8')) > 1000 THEN 'L' ELSE 'T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.parallel), 'AL32UTF8')) END || '|Z' AS DBWARP_BP_FULL_FRAME
FROM (SELECT version, status, parallel FROM SYS.V_$INSTANCE) q) DBWARP_BP_BOUNDED_ROWS;
PROMPT DBWARP_BP_RAW|Q|27|E
