CASE WHEN q.name IS NULL THEN 'N' WHEN UTL_RAW.LENGTH(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.name), 'AL32UTF8')) > 1000 THEN 'L' ELSE 'T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.name), 'AL32UTF8')) END || '|' ||
