CASE WHEN q.isdefault IS NULL THEN 'N' WHEN UTL_RAW.LENGTH(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.isdefault), 'AL32UTF8')) > 1000 THEN 'L' ELSE 'T' || RAWTOHEX(UTL_I18N.STRING_TO_RAW(TO_CHAR(q.isdefault), 'AL32UTF8')) END || '|Z' AS DBWARP_BP_FULL_FRAME
FROM (SELECT name, value, isdefault FROM SYS.V_$PARAMETER WHERE LOWER(name) IN ('cpu_count','memory_target','sga_target','sga_max_size')) q) DBWARP_BP_BOUNDED_ROWS;
PROMPT DBWARP_BP_RAW|Q|29|E
SELECT 'DBWARP_BP_RAW|X|29|' || TO_CHAR(ROUND(
(CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS DATE) - DATE '1970-01-01') * 86400000),
'FM99999999999999999990', 'NLS_NUMERIC_CHARACTERS=''.,''') FROM DUAL;
SPOOL OFF
